"""Declared ADX table schemas (schemas.json, generated by tools/gen_schemas.py from Volatility's source).

Every table is created up front once the OS is known, with the column types Volatility declares.
That gives the workbook stable tables to query: a plugin that fails or finds nothing still leaves
an empty, correctly typed table behind instead of no table at all.
"""

from __future__ import annotations

import json
from functools import cached_property
from pathlib import Path

from .csvnorm import Column, ColumnType
from .models import OsFamily

SCHEMA_FILE = Path(__file__).with_name("schemas.json")


class TableSchemas:
    def __init__(self, path: Path = SCHEMA_FILE):
        self.path = path

    @cached_property
    def _raw(self) -> dict[str, dict[str, str]]:
        return json.loads(self.path.read_text(encoding="utf-8"))

    def for_os(self, os_family: OsFamily | None) -> dict[str, list[Column]]:
        """Tables for one OS plus VolAutolity's own tables. Keys ending in `*` are name patterns."""
        tables = dict(self._raw["common"])
        if os_family is None:  # no profile resolved: only the diagnostics table is relevant
            tables["banners"] = self._raw[OsFamily.WINDOWS.value]["banners"]
        else:
            tables.update(self._raw[os_family.value])
        return {name: _parse(spec) for name, spec in tables.items()}

    @staticmethod
    def lookup(tables: dict[str, list[Column]], table: str) -> list[Column] | None:
        if table in tables:
            return tables[table]
        for pattern, columns in tables.items():
            if pattern.endswith("*") and table.startswith(pattern[:-1]):
                return columns
        return None


def _parse(spec: str) -> list[Column]:
    columns = []
    for item in spec.split(","):
        name, kind = item.split(":")
        columns.append(Column(name, ColumnType(kind)))
    return columns
